<header><span class="eyebrow">A conversation can be a starting point</span><h1>Book time with Waithaka</h1><?php if(!empty($hostIdentity['id'])):?><p>Booking context: <?=e($hostIdentity['label'])?> · replies use this booking identity.</p><?php endif;?><p>Explore an idea, discuss a partnership or start a useful conversation.</p><div class="booking-principles"><span>Times shown in your chosen timezone</span><span>Calendar conflicts checked before confirmation</span><span>Manage, reschedule or cancel with your private link</span></div></header>
<?php foreach(flashes()as$f):?><p class="notice" role="status"><?=e($f['message'])?></p><?php endforeach;?><?php if($error):?><p class="notice error" role="alert"><?=e($error)?></p><?php endif;?>
<?php if($manage):?><section class="comm-panel"><span class="comm-badge"><?=e($manage['status'])?></span><h2><?=e($cfg['types'][$manage['type']]['name'])?></h2><p>Hello <?=e($manage['first'])?>. <?=e((new DateTimeImmutable('@'.$manage['start']))->setTimezone(comm_zone($manage['timezone']))->format('l, j F Y · H:i T'))?></p><?php if($manage['status']==='requested'):?><p>Your selected time is reserved while Waithaka reviews your request. It is not yet a confirmed appointment.</p><?php elseif($manage['status']==='confirmed'):?><p>Your appointment is confirmed. Calendar invitations and service emails are processed separately.</p><p>Meeting method: <?=e(booking_method_text($manage))?></p><?php if($manage['join']===''&&($manage['platform']??'google_meet')==='google_meet'):?><p><?=($manage['conference_status']??'pending')==='unavailable'?'Please contact Waithaka for your meeting link.':'Your meeting link is being prepared. Check your calendar invitation or return to this page shortly.'?></p><?php endif;?><?php if($manage['join']):?><a class="wbtn primary" href="<?=e($manage['join'])?>" rel="noopener noreferrer" target="_blank">Join meeting</a><?php endif;?><?php elseif($manage['status']==='review'):?><p>Your request is saved and needs calendar review. Please contact Waithaka before submitting again.</p><?php endif;?><?php if(in_array($manage['status'],['requested','confirmed'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="cancel"><label>Cancellation reason<textarea name="reason" required maxlength="1000"></textarea></label><button class="wbtn" data-confirm-action="Cancel this booking?">Cancel booking</button></form><?php endif;?><?php if(in_array($manage['status'],['requested','confirmed'],true)):?><details><summary>Let Waithaka know I will be late</summary><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="late"><label>Expected delay in minutes<input type="number" name="late_minutes" min="1" max="240" required></label><label>Reason<textarea name="reason" required maxlength="1000"></textarea></label><button class="wbtn">Notify Waithaka</button></form></details><?php endif;?>
<p class="comm-muted">Keep this private link to manage your booking. It is not a newsletter subscription.</p></section><?php endif;?>
