<?php if(empty($cfg['enabled'])):?><section class="comm-panel"><span class="comm-badge">Availability temporarily closed</span><h2>Choose from available meeting times</h2><p>Booking opens when the connected calendars can be checked reliably. No times are being offered while those checks are unavailable. Please return later or <a href="<?=url('/contact')?>">contact Waithaka</a> for a general enquiry.</p></section>
<?php elseif(!$manage||in_array($manage['status'],['requested','confirmed'],true)):?>
<div class="booking-grid"><aside class="comm-panel"><h2><?=$manage?'Choose a new time':'1. Choose a conversation'?></h2><?php if(!$manage):?><?php foreach($cfg['types']as$k=>$t):if(empty($t['enabled']))continue;?><a class="booking-type" href="<?=url('/book?'.http_build_query(['type'=>$k,'date'=>$date,'timezone'=>$zone,'host'=>$hostIdentity['id']??'']))?>" <?=$type===$k?'aria-current="true"':''?>><strong><?=e($t['name'])?></strong><span><?=(int)$t['minutes']?> minutes · Subject to briefing & approval</span></a><?php endforeach;?><?php else:?><p><?=e($cfg['types'][$type]['name'])?></p><?php endif;?><p>Availability is checked across Waithaka’s selected calendars. Your timezone can be changed below.</p></aside>
<section class="comm-panel"><h2><?=$manage?'Reschedule':'2. Find a time'?></h2><div class="booking-selection"><strong><?=e($cfg['types'][$type]['name'])?></strong><span><?=(int)$cfg['types'][$type]['minutes']?> minutes · Report reviewed before confirmation</span></div>
<nav class="booking-week" aria-label="Choose an upcoming date"><?php $bookingDay=new DateTimeImmutable('tomorrow',comm_zone($cfg['timezone']));for($dayIndex=0;$dayIndex<7;$dayIndex++):$choice=$bookingDay->modify('+'.$dayIndex.' days');$choiceDate=$choice->format('Y-m-d');?><a href="<?=url(($manage?path_only():'/book').'?'.http_build_query(['type'=>$type,'date'=>$choiceDate,'timezone'=>$zone,'host'=>$hostIdentity['id']??'']))?>" <?=$date===$choiceDate?'aria-current="date"':''?>><?=e($choice->format('D'))?><strong><?=e($choice->format('j M'))?></strong></a><?php endfor;?></nav><form method="get" class="comm-fields"><input type="hidden" name="host" value="<?=e($hostIdentity['id']??'')?>"><input type="hidden" name="type" value="<?=e($type)?>"><label>Date in host timezone (<?=e($cfg['timezone'])?>)<input type="date" name="date" value="<?=e($date)?>" required></label><label>Show times in<select name="timezone" data-visitor-timezone><?php foreach(DateTimeZone::listIdentifiers()as$tz):?><option <?=$zone===$tz?'selected':''?>><?=e($tz)?></option><?php endforeach;?></select></label><button class="wbtn">Show available times</button></form>
<?php if(!$slots):?><p class="comm-empty">No verified times available for this date. Try another date or <a href="<?=url('/contact')?>">send a message</a>.</p><?php else:?><form method="post" class="booking-form" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="host" value="<?=e($hostIdentity['id']??'')?>"><input type="hidden" name="type" value="<?=e($type)?>"><input type="hidden" name="date" value="<?=e($date)?>"><input type="hidden" name="timezone" value="<?=e($zone)?>"><input type="hidden" name="request_id" value="<?=bin2hex(random_bytes(16))?>"><?php if($manage):?><input type="hidden" name="action" value="reschedule"><?php endif;?><fieldset><legend>Available start times · <?=e($zone)?></legend><div class="booking-slots"><?php foreach($slots as$s):?><label><input type="radio" name="slot" value="<?=$s?>" required><span><?=e((new DateTimeImmutable('@'.$s))->setTimezone(comm_zone($zone))->format('D j M · H:i'))?></span></label><?php endforeach;?></div></fieldset>
<?php if(!$manage):?><h2>3. Your details</h2><div class="comm-fields"><label>First name<input name="first" maxlength="80" autocomplete="given-name" required></label><label>Last name<input name="last" maxlength="80" autocomplete="family-name" required></label></div><label>Email<input type="email" name="email" maxlength="254" autocomplete="email" required></label><label>What would you like to discuss?<textarea name="agenda" maxlength="1500" rows="4" required></textarea></label><label>Preferred meeting method<select name="platform"><?php foreach(booking_platforms()as$key=>$label):?><option value="<?=e($key)?>" <?=$key==='google_meet'?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><p>Google Meet is the default. All alternatives and suggested arrangements are subject to Waithaka’s approval.</p><label>Phone / messaging contact · for Phone, WhatsApp or Signal<input name="platform_contact" maxlength="120" placeholder="+254… or Signal username"></label><label>If Other, suggest the platform or arrangement<textarea name="platform_detail" maxlength="500" rows="2"></textarea></label><input type="hidden" name="document_provider" value="<?=e(booking_document_provider($cfg))?>"><label>Supporting document · optional<input type="file" name="booking_document" accept=".pdf,.png,.jpg,.jpeg"></label><p>One PDF, JPEG or PNG up to 4 MB. Keep sensitive identifiers out of the document. It remains private to the host.</p><label><input type="checkbox" name="document_consent" value="1">If I attach a document, I allow it and my agenda to be sent to <?=e(booking_provider_name(booking_document_provider($cfg)))?> for a private briefing draft, which Waithaka will review before deciding.</label><div hidden aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label><input type="checkbox" name="consent" required>I agree to the use of my details for this appointment and its service notifications. <a href="<?=url('/privacy')?>">Privacy</a></label><p>This does not subscribe you to marketing emails.</p><?php endif;?><button class="wbtn primary"><?=$manage?'Confirm new time':'Request this meeting'?></button><p class="comm-muted">The selected time is rechecked when you submit. New bookings require Waithaka’s approval after a briefing report is prepared.</p></form><?php endif;?></section></div>
<?php endif;?></div><script src="<?=asset('js/communication.js')?>" defer></script><script src="<?=asset('js/booking-method.js')?>" defer></script>

